def build() -> list[dict]:
    counters: dict[str, int] = {}
    records: list[dict] = []
    for doc, section, question, answer, facts, category, difficulty in Q:
        counters[doc] = counters.get(doc, 0) + 1
        records.append(
            {
                "id": f"{doc}-{counters[doc]:02d}",
                "question": question,
                "answer": answer,
                "expected_facts": facts,
                "source": {"document_id": slugify(DOCS[doc]), "document_title": DOCS[doc], "section": section},
                "category": category,
                "difficulty": difficulty,
            }
        )
    return records


def main() -> None:
    records = build()
    assert len(records) == 150, f"expected 150 questions, have {len(records)}"
    per_doc = {}
    for r in records:
        per_doc[r["source"]["document_id"]] = per_doc.get(r["source"]["document_id"], 0) + 1
    with OUT.open("w", encoding="utf-8") as fh:
        for r in records:
            fh.write(json.dumps(r, ensure_ascii=False) + "\n")
    print(f"wrote {len(records)} questions to {OUT}")
    for doc, n in per_doc.items():
        print(f"  {doc}: {n}")


if __name__ == "__main__":
    main()
